const ASSETS = {
  '/assets/index-DFvVH-Ua.css': { type: 'text/css; charset=utf-8', b64: '' },
  '/assets/index-DyGo-39u.js': { type: 'application/javascript; charset=utf-8', b64: '' },
  '/index.html': { type: 'text/html; charset=utf-8', b64: '' },
}

// ============================================================
// 辅助函数
// ============================================================
function atobSafe(str) {
  try { return atob(str) } catch(e) { return null }
}

function serve(path) {
  const asset = ASSETS[path]
  if (!asset) return null
  try {
    const decoded = atobSafe(asset.b64)
    if (!decoded) return null
    const bytes = Uint8Array.from(decoded, c => c.charCodeAt(0))
    const body = new TextDecoder().decode(bytes)
    return new Response(body, {
      headers: {
        'Content-Type': asset.type,
        'Cache-Control': 'public, max-age=31536000, immutable',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS',
        'Access-Control-Allow-Headers': '*',
      },
    })
  } catch(e) {
    return null
  }
}

async function handleRequest(request) {
  if (request.method === 'OPTIONS') {
    return new Response(null, {
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS',
        'Access-Control-Allow-Headers': '*',
        'Access-Control-Max-Age': '86400',
      },
    })
  }

  const url = new URL(request.url)
  let path = url.pathname

  // 去除尾部斜杠（除了根路径）
  if (path.endsWith('/') && path !== '/') path = path.slice(0, -1)

  // 尝试精确匹配
  const result = serve(path)
  if (result) return result

  // 尝试带 index.html
  const indexResult = serve(path + '/index.html')
  if (indexResult) return indexResult

  // SPA fallback: 对于非静态资源请求，返回 index.html
  // 判断是否为静态资源
  const staticExtensions = ['.js', '.css', '.png', '.jpg', '.jpeg', '.gif', '.svg', '.ico', '.webp', '.woff', '.woff2', '.ttf', '.json', '.map']
  const ext = path.substring(path.lastIndexOf('.'))
  if (!staticExtensions.includes(ext)) {
    const html = serve('/')
    if (html) return html
  }

  return new Response('Not Found', { status: 404 })
}

addEventListener('fetch', event => {
  event.respondWith(handleRequest(event.request))
})
